prompt Loading MED_NURSE_TEMPLETE...
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', 'SHZICU', '术后转ICU', '患者入手术室在“气管插管静吸复合麻醉”下行“ 术”。术后诊断“ ”。术毕于 ： 转入ICU。转入时麻醉未清醒，双侧瞳孔等大等圆，对光放射消失，报告本组医生  。嘱继续观察。转入时气管插管带入，插入深度距门齿  cm。立即接呼吸机  模式辅助呼吸，f 次/分，VT ml/次，FiO2为 %,PEEP cmH2O。右锁骨下静脉置管输液通畅，穿刺点距蝶形塑料接头 cm，穿刺点及周围皮肤无红肿，外接镇痛泵持续镇痛。 部敷料清洁干燥。持续  管引流通畅，引流出  色  液体。  部皮肤有一 ×　cm2皮肤压红。留置尿管通畅，尿色黄。遵医嘱重症监护，暂禁食。吸痰Prn。取平卧位休息，加盖棉被给予保暖。加护床栏，防止坠床。为防止拔除各种管道，给予约束带约束双上肢，约束处皮肤无红肿，肢端温暖，血运良好。心电监护示：窦性心律，律齐。', 'SHZICU');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', 'YBJB', '一般交班', '胃管通畅。气管套管通畅，痰多，黄稠，及时湿化抽吸。仍以呼吸机？？？模式辅助呼吸，VT450ml/次，Fio2为45%，压力支持位12cmH2O。（给予雾化面罩湿化给氧，氧流量为3L/min。或 鼻导管给氧通畅，氧流量为3L/min。）右锁骨下静脉置管补液通畅，穿刺点距蝶形塑料接头8cm，穿刺点及周围皮肤无红肿。外接压力换能器持续监测CVP.仍给予多巴胺微泵入维持血压。留置导尿通畅，尿色黄。监测Q1h尿量。取半卧位休息/抬高床头30°卧位休息。心电监护示：窦性心律，律齐。', 'YBJB');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', '32', '血气分析', '医生查看病人，血气分析示Na: mmol/l,K:mmol/l,Tco2:mmol/l,Ica:mmol/l,HCT:,Hb:g/l,PH:,Pco2:,Kpa,Po2:,Kpa,Hco3:mmol/l,BEecf:mmol/l,So2:%', 'XQFX');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', '4', 'ICU病情小结', '患者于 在全麻下行 手术，手术完毕返回ICU，  麻醉  清醒，不带气管插管，未行呼吸机辅助呼吸，次/分，于 行呼吸机过渡，拔除气管插管，鼻导管', 'ICUBQXJ');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', '10', '出院小结(普通）', '持续给氧通畅，心电监护示窦性心律，律齐，持续导尿通畅，遵嘱办理出院手续，指导保持各管道通畅，指导定时翻身拍背及活动肢体，告知饮食原则和皮肤护理的方法。', 'CYXJPTD');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', '34', '死亡小结', '心电图呈一直线，无自主呼吸，双侧瞳孔散大固定，临床死亡，予尸体护理。', 'SWXJ');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', 'XJ(CG)', '小结（常规）', '头晕，疲乏，持续氧气吸入3L/分，心电监护示窦性心律，律齐。取床头抬高30°卧位休息。胃管通畅。持续导尿通畅，尿液呈淡黄色。', 'XJ(CG)');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', 'XJ(QQQC)', '小结（气切气插）', '疲乏，气促，持续气管切开（气管插管）处给氧3L/分，持续气道湿化。心电监护示窦性心律，律齐。取床头抬高30°卧位休息。痰多，呈淡黄色。胃管通畅。持续导尿通畅，呈淡黄色。', 'XJ(QQQC)');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', 'XJ(HXJ)', '小结（呼吸机）', '疲乏，气促，持续气管切开处接呼吸机辅助呼吸，呼吸模式为压力控制SIMV，呼吸频率为15次/分，呼吸压力为15cmH2O，FiO2为40％，心电监护示窦性心律，律齐。痰多，呈淡黄色。取床头抬高30°卧位休息。胃管通畅。持续导尿通畅，尿液呈淡黄色。', 'XJ(HXJ)');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', 'RY(PT)', '入院(普通)', '患者于11:10 由急诊科平车入院。入院时，神志呈昏迷状态。立即予以鼻导管给氧.氧流量3L/min。左上肢静脉留置针输液通畅，穿刺点及周围皮肤无红肿。大小便失禁,以予及时清除，保持床单位及皮肤清洁干燥。吸痰Prn。遵医嘱重症监护，鼻饲流质。加护床栏，防止坠床。双上肢约束带约束，防止意外拔管，约束处皮肤无红肿，肢端温暖，血运良好。全身皮肤完整。心电监护示窦性心律，律齐。取床头抬高30°卧位休息。', 'RY(PT)');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', 'ZC', '转出', '胃管通畅。气管套管通畅，痰多，黄稠，及时湿化抽吸。持续鼻导管给氧3L/分。右上肢静脉留置针补液通畅，穿刺点及周围皮肤无红肿。右锁骨下静脉置管补液通畅，穿刺点距蝶型塑料接头6cm，穿刺点及周围皮肤无红肿。留置导尿通畅，尿色黄。取半卧位休息。心电监护示：窦性心律，律齐。遵嘱转 区继续治疗。', 'ZC');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', 'SSZR', '手术转入', '患者入手术室在“全麻”下行“ 术”。术后诊断“ ”。术毕于 ： 转入ICU。转入时麻醉未清醒，双侧瞳孔等大等圆，对光放射消失，报告本组医生  。嘱继续观察。转入时气管插管带入，插入深度距门齿  cm。立即接呼吸机  模式辅助呼吸，f 次/分，VT ml/次，FiO2为 %,PEEP cmH2O。右锁骨下静脉置管输液通畅，穿刺点距蝶形塑料接头 cm，穿刺点及周围皮肤无红肿，外接镇痛泵持续镇痛。 部敷料清洁干燥。持续  管引流通畅，引流出  色  液体。  部皮肤有一 ×　cm压红。留置尿管通畅，尿色黄。遵医嘱重症监护，暂禁食。吸痰Prn。取平卧位休息，加盖棉被给予保暖。加护床栏，防止坠床。为防止拔除各种管道，给予约束带约束双上肢，约束处皮肤无红肿，肢端温暖，血运良好。心电监护示：窦性心律，律齐。', 'SSZR');
insert into med_nurse_templete (WARD_CODE, TEMPLETE_CODE, TEMPLETE_NAME, TEMPLETE_DESC, INPUT_CODE)
values ('0000310', '78', '出院小结（自动出院）', '仍呼吸球囊辅助呼吸，心电监护示窦性心律，律齐，持续导尿通畅，遵嘱办理出院手续，指导家属保持各管道通畅，指导呼吸球囊辅助呼吸的方法。', 'CYXJDZDC');
commit;

